        failures: [['Database CPU at 100% after rollout', 'Concurrency no longer capped by threads', 'Size the pool; add semaphores'], ['Latency rises instead of errors', 'Unbounded waiting for connections', 'Acquisition timeouts'], ['Memory grows with thread count', 'Per-thread caches in ThreadLocal', 'Shared immutable objects or scoped values'], ['Image processing slows everything', 'CPU work on virtual threads', 'Bounded platform executor for CPU work']],
